"use client"

import type { CSSProperties, HTMLAttributes } from "react"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./spinner.css"

const SIZES = ["xs", "sm", "md", "lg", "xl"] as const
const THICKNESSES = [
  "thin",
  "normal",
  "medium",
  "thick",
  "extra-thick",
] as const
const SPEEDS = ["slow", "normal", "fast", "faster"] as const

export type SpinnerSize = (typeof SIZES)[number]
export type SpinnerThickness = (typeof THICKNESSES)[number]
export type SpinnerSpeed = (typeof SPEEDS)[number]
export type SpinnerDirection =
  "clockwise" | "counter-clockwise" | "counterclockwise"

export interface SpinnerProps extends HTMLAttributes<HTMLSpanElement> {
  /** Preset or any CSS length, e.g. "40px" */
  size?: SpinnerSize | (string & {})
  /** Preset or any CSS length, e.g. "3px" */
  thickness?: SpinnerThickness | (string & {})
  /** Preset or any CSS time, e.g. "900ms" */
  speed?: SpinnerSpeed | (string & {})
  direction?: SpinnerDirection
  /** Color of the moving arc (default: currentColor) */
  color?: string
  /** Color of the track */
  mutedColor?: string
  /** Accessible label (default: "Loading") */
  label?: string
}

type SpinnerStyle = CSSProperties & {
  "--np-spinner-size"?: string
  "--np-spinner-thickness"?: string
  "--np-spinner-speed"?: string
  "--np-spinner-color"?: string
  "--np-spinner-muted-color"?: string
}

const isPreset = <T extends readonly string[]>(
  list: T,
  value: string
): value is T[number] => (list as readonly string[]).includes(value)

export function Spinner({
  size,
  thickness,
  speed,
  direction = "clockwise",
  color,
  mutedColor,
  label = "Loading",
  className = "",
  style,
  ...rest
}: SpinnerProps) {
  const customStyle: SpinnerStyle = { ...style }
  const dataAttrs: Record<string, string> = {}

  // Preset -> data attribute (handled by CSS). Anything else -> inline CSS variable.
  if (size) {
    if (isPreset(SIZES, size)) dataAttrs["data-size"] = size
    else customStyle["--np-spinner-size"] = size
  }
  if (thickness) {
    if (isPreset(THICKNESSES, thickness))
      dataAttrs["data-thickness"] = thickness
    else customStyle["--np-spinner-thickness"] = thickness
  }
  if (speed) {
    if (isPreset(SPEEDS, speed)) dataAttrs["data-speed"] = speed
    else customStyle["--np-spinner-speed"] = speed
  }
  if (color) customStyle["--np-spinner-color"] = color
  if (mutedColor) customStyle["--np-spinner-muted-color"] = mutedColor

  return (
    <span
      data-slot="spinner"
      role="status"
      aria-label={label}
      className={cn(`np-spinner`, className)}
      data-direction={direction}
      style={customStyle}
      {...dataAttrs}
      {...rest}
    />
  )
}

:root {
  --np-spinner-muted-color: rgba(0, 0, 0, 0.2);
  --np-spinner-color: currentColor;
}

.dark {
  --np-spinner-color: currentColor; /* red, #123456, rgba(255, 0, 0, 0.5) */
  --np-spinner-muted-color: rgba(255, 255, 255, 0.4);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --np-spinner-color: currentColor;
    --np-spinner-muted-color: rgba(255, 255, 255, 0.4);
  }
}

.np-spinner,
[data-np-spinner] {
  --np-spinner-size: 1rem;
  --np-spinner-thickness: clamp(1px, calc(var(--np-spinner-size) * 0.1), 4px);
  --np-spinner-speed: 750ms;

  display: inline-block;
  width: var(--np-spinner-size);
  height: var(--np-spinner-size);

  flex-shrink: 0;

  border: var(--np-spinner-thickness) solid var(--np-spinner-muted-color);
  border-right-color: var(--np-spinner-color);

  border-radius: 50%;

  color: var(--np-spinner-color);

  animation: np-spinner-spin var(--np-spinner-speed) linear infinite;
}

/* Size */

[data-size="xs"],
.np-spinner-xs {
  --np-spinner-size: 0.75rem;
}

[data-size="sm"],
.np-spinner-sm {
  --np-spinner-size: 0.875rem;
}

[data-size="md"],
.np-spinner-md {
  --np-spinner-size: 1rem;
}

[data-size="lg"],
.np-spinner-lg {
  --np-spinner-size: 1.5rem;
}

[data-size="xl"],
.np-spinner-xl {
  --np-spinner-size: 2rem;
}

/* Thickness */

[data-thickness="thin"],
.np-spinner-thin {
  --np-spinner-thickness: 1px;
}

[data-thickness="normal"],
.np-spinner-thickness-normal {
  --np-spinner-thickness: 2px;
}

[data-thickness="medium"],
.np-spinner-thickness-medium {
  --np-spinner-thickness: 2.5px;
}

[data-thickness="thick"],
.np-spinner-thickness-thick {
  --np-spinner-thickness: 4px;
}

[data-thickness="extra-thick"],
.np-spinner-thickness-extra-thick {
  --np-spinner-thickness: 6px;
}

/* Speed */

[data-speed="slow"],
.np-spinner-slow {
  --np-spinner-speed: 1.25s;
}

[data-speed="normal"],
.np-spinner-normal {
  --np-spinner-speed: 750ms;
}

[data-speed="fast"],
.np-spinner-fast {
  --np-spinner-speed: 500ms;
}

[data-speed="faster"],
.np-spinner-faster {
  --np-spinner-speed: 300ms;
}

/* Direction */

[data-direction="clockwise"],
.np-spinner-clockwise {
  animation-name: np-spinner-spin;
}

[data-direction="counter-clockwise"],
[data-direction="counterclockwise"],
.np-spinner-counter-clockwise,
.np-spinner-counterclockwise {
  animation-name: np-spinner-spin-reverse;
}

/* Animation */

@keyframes np-spinner-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes np-spinner-spin-reverse {
  to {
    transform: rotate(-360deg);
  }
}

/* Reduced motion support */

@media (prefers-reduced-motion: reduce) {
  .np-spinner,
  [data-np-spinner] {
    animation-duration: 1.5s;
  }
}
